export const buildContract={target:'windows-x64',renderer:'WebView2/WebGL2',configurations:['development','release'],content:'All Assets except disabled scenes, plus referenced project files; C++ compiled ahead of time',output:'Builds/<profile id>/<unique build id>',maxProfiles:32,maxScenes:256};
export function resolveBuildPath(name,redirects={}){const seen=new Set();for(let i=0;i<33;i++){if(typeof name!=='string'||/[\\:\x00-\x1f]/.test(name)||name.startsWith('/')||name.split('/').some(s=>!s||s==='.'||s==='..'))throw Error('패키지 참조 경로 오류');const from=Object.keys(redirects).sort((a,b)=>b.length-a.length).find(p=>name===p||name.startsWith(p+'/'));if(!from)return name;if(seen.has(from))throw Error('패키지 참조 순환');seen.add(from);name=redirects[from]+name.slice(from.length);}throw Error('패키지 참조 깊이 초과');}
export function defaultBuildProfile(session){return {id:'windows',name:'Windows',configuration:'development',productName:session.name,width:1280,height:720,scenes:[{path:session.startupScene,enabled:true}]};}
export function validBuildProfile(p){return p&&/^[a-z][a-z0-9_-]{0,39}$/.test(p.id)&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=80&&typeof p.productName==='string'&&p.productName.trim().length>0&&p.productName.length<=80&&!/[\x00-\x1f]/.test(p.productName)&&buildContract.configurations.includes(p.configuration)&&Number.isInteger(p.width)&&p.width>=320&&p.width<=7680&&Number.isInteger(p.height)&&p.height>=240&&p.height<=4320&&Array.isArray(p.scenes)&&p.scenes.length>0&&p.scenes.length<=256&&p.scenes.some(s=>s.enabled)&&new Set(p.scenes.map(s=>s.path)).size===p.scenes.length&&p.scenes.every(s=>s&&typeof s.path==='string'&&s.path.startsWith('Assets/')&&s.path.endsWith('.hbscene.json')&&!/[\\:\x00-\x1f]/.test(s.path)&&!s.path.split('/').some(v=>!v||v==='.'||v==='..')&&typeof s.enabled==='boolean');}
